using System.Collections.Generic; using Verse; using Verse.AI;
namespace LiAIChat.Commentary { public class JobDriver_WriteEarthCommentary : JobDriver { private Thing Desk { get { return job.targetA.Thing; } } private Thing_EarthCommentaryManuscript Book { get { return job.targetB.Thing as Thing_EarthCommentaryManuscript; } } public override bool TryMakePreToilReservations(bool e) { return pawn.Reserve(Desk, job, 1, -1, null, e); } protected override IEnumerable<Toil> MakeNewToils() { this.FailOnDespawnedNullOrForbidden(TargetIndex.A); this.FailOnDespawnedNullOrForbidden(TargetIndex.B); this.FailOn(() => pawn.Drafted); yield return Toils_Goto.GotoThing(TargetIndex.A, PathEndMode.InteractionCell); Toil t=ToilMaker.MakeToil("WriteEarthCommentary"); t.defaultCompleteMode=ToilCompleteMode.Delay; t.defaultDuration=2500; t.tickAction=()=>CommentaryIdleWritingManager.AddWritingTick(Book); t.WithProgressBarToilDelay(TargetIndex.B); yield return t; } } }
